/*
 * Exact complementary 50 % square wave, generated by one hardware PWM slice.
 *
 * GP6 = PWM channel A, GP7 = PWM channel B of the same slice.  Both channels
 * share one counter and one wrap value, and channel B is inverted, so B is
 * high for exactly the part of the period in which A is low.  The edges are
 * produced by the PWM peripheral: no interrupt, no software deadline, no
 * jitter, and therefore no stepped or missing pulses.
 *
 * For a period of N ticks, A is high for N/2 ticks and B for N/2 ticks.  With
 * N = 16666 at 60 Hz that is 8333/8333, i.e. exactly 50.000 % on each pin and
 * exactly 16666 us (16.666 ms) per cycle.
 */

#include "waveform.h"

#include "board.h"
#include "hardware/clocks.h"
#include "hardware/gpio.h"
#include "hardware/pwm.h"
#include "pico/stdlib.h"

#define TICK_HZ            1000000u   /* divider target: 1 us per count */
#define MAX_WRAP           65535u
#define MAX_PERIOD_TICKS   65534u     /* even, so N/2 is exact */
#define DIV16_MAX          4095u      /* 255 + 15/16 */
#define DIV16_MIN          16u        /* 1 */

static uint slice;
static uint32_t sys_hz;
static uint32_t ticks;                /* wrap + 1 */
static uint32_t period_us;
static uint16_t freq_hz = PWM_DEFAULT_HZ;
static uint16_t actual_hz = PWM_DEFAULT_HZ;
static bool limited;
static bool running;

static uint32_t clamp_frequency(uint32_t hz)
{
    if (hz < PWM_MIN_HZ) {
        hz = PWM_MIN_HZ;
    }
    if (hz > PWM_MAX_HZ) {
        hz = PWM_MAX_HZ;
    }
    return hz;
}

static void pins_off(void)
{
    gpio_set_function(PIN_DRV_A, GPIO_FUNC_SIO);
    gpio_set_function(PIN_DRV_B, GPIO_FUNC_SIO);
    gpio_set_dir(PIN_DRV_A, GPIO_OUT);
    gpio_set_dir(PIN_DRV_B, GPIO_OUT);
    gpio_put(PIN_DRV_A, 0);
    gpio_put(PIN_DRV_B, 0);
}

static void pins_pwm(void)
{
    gpio_set_function(PIN_DRV_A, GPIO_FUNC_PWM);
    gpio_set_function(PIN_DRV_B, GPIO_FUNC_PWM);
}

/*
 * Program wrap, divider and levels.  Level is always ticks/2 on both channels,
 * so the duty cycle is exactly 50 % (ticks is forced even).
 */
static void apply(void)
{
    uint32_t f = clamp_frequency(freq_hz);
    uint32_t t;
    uint32_t div16;
    bool clipped = false;

    if ((TICK_HZ / f) <= MAX_PERIOD_TICKS) {
        /* 1 us ticks fit in the 16-bit counter. */
        t = TICK_HZ / f;
        if (t & 1u) {
            t--;                       /* keep N even: exact 50 % */
        }
        div16 = (uint32_t)(((uint64_t)sys_hz * 16u + TICK_HZ / 2u) / TICK_HZ);
    } else {
        /*
         * Low frequency: use the longest counter and slow the slice down.
         * The integrator is 8.4 fixed point, so very low frequencies will
         * clip; report that through waveform_is_limited().
         */
        uint64_t denom = (uint64_t)f * MAX_PERIOD_TICKS;
        uint64_t d = ((uint64_t)sys_hz * 16u + denom / 2u) / denom;

        t = MAX_PERIOD_TICKS;
        if (d > DIV16_MAX) {
            d = DIV16_MAX;
            clipped = true;
        }
        div16 = (uint32_t)d;
    }

    if (div16 < DIV16_MIN) {
        div16 = DIV16_MIN;
    }
    if (t < 2u) {
        t = 2u;
    }

    ticks = t;
    pwm_set_clkdiv_int_frac4(slice, (uint8_t)(div16 >> 4), (uint8_t)(div16 & 0x0Fu));
    pwm_set_wrap(slice, (uint16_t)(t - 1u));
    pwm_set_chan_level(slice, PWM_CHAN_A, (uint16_t)(t / 2u));
    pwm_set_chan_level(slice, PWM_CHAN_B, (uint16_t)(t / 2u));

    /* Achieved period in microseconds, rounded: t * div16 / (sys * 16). */
    uint64_t num = (uint64_t)ticks * div16 * 1000000u;
    uint64_t den = (uint64_t)sys_hz * 16u;
    period_us = (uint32_t)((num + den / 2u) / den);

    uint32_t hz = (1000000u + period_us / 2u) / period_us;
    actual_hz = (uint16_t)hz;
    limited = clipped;
}

void waveform_init(void)
{
    slice = pwm_gpio_to_slice_num(PIN_DRV_A);
    sys_hz = clock_get_hz(clk_sys);

    pins_off();
    gpio_set_drive_strength(PIN_DRV_A, GPIO_DRIVE_STRENGTH_8MA);
    gpio_set_drive_strength(PIN_DRV_B, GPIO_DRIVE_STRENGTH_8MA);
    gpio_disable_pulls(PIN_DRV_A);
    gpio_disable_pulls(PIN_DRV_B);

    /* Channel B inverted: B is the exact complement of A. */
    pwm_set_output_polarity(slice, false, true);
    pwm_set_enabled(slice, false);
    pwm_set_counter(slice, 0);

    apply();
}

void waveform_on(void)
{
    if (running || ticks == 0) {
        return;
    }

    /* Restart at counter zero so the first high time is a full half-period. */
    pwm_set_enabled(slice, false);
    pwm_set_counter(slice, 0);
    pins_pwm();
    pwm_set_enabled(slice, true);
    running = true;
}

void waveform_off(void)
{
    running = false;
    pwm_set_enabled(slice, false);
    pwm_set_counter(slice, 0);
    pins_off();
}

bool waveform_is_on(void)
{
    return running;
}

void waveform_set_frequency(uint16_t hz)
{
    hz = (uint16_t)clamp_frequency(hz);
    if (hz == freq_hz) {
        return;
    }

    freq_hz = hz;

    if (running) {
        /* Stop cleanly, reprogram, restart at phase 0. */
        pwm_set_enabled(slice, false);
        pwm_set_counter(slice, 0);
        apply();
        pwm_set_enabled(slice, true);
    } else {
        apply();
    }
}

/* Duty is fixed at 50 % in this build; the value is accepted but has no effect. */
void waveform_set_duty(uint8_t pct)
{
    (void)pct;
}

uint16_t waveform_get_frequency(void)
{
    return actual_hz;
}

uint8_t waveform_get_duty(void)
{
    return 50;
}

void waveform_task(void)
{
    /* Nothing to do: the waveform is entirely hardware generated. */
}

uint32_t waveform_get_period_us(void)
{
    return period_us;
}

uint32_t waveform_get_on_us(void)
{
    return period_us / 2u;
}

bool waveform_is_limited(void)
{
    return limited;
}
